class DivZero(Exception):
    """Raised by safe_div when the divisor is zero; carries the numerator."""

    a: int

    def __init__(self, a: int) -> None:
        super().__init__(a)
        self.a = a


def safe_div(a: int, b: int) -> int:
    """Return a // b. Raise DivZero(a) when b is zero."""
    if b == 0:
        raise DivZero(a)
    return a // b


def test_safe_div_basic() -> None:
    assert safe_div(7, 2) == 3
    assert safe_div(-7, 2) == -4
    assert safe_div(0, 5) == 0


def test_safe_div_by_zero_raises_with_numerator() -> None:
    import pytest

    with pytest.raises(DivZero) as excinfo:
        safe_div(42, 0)
    assert excinfo.value.a == 42
